fn should_end_object_finish_kill_priority_battle(version, rnd, player, data, main_objective) -> bool

// [1216] 대상 게이트 (마스크 접힘: (mo & 0xFFFE) == 0x0300)
if !(main_objective.tag in {0=Morgard, 1=Serpen} && main_objective.phase == ObjectPhase::Hunt) {
    return false;               // with_battle 은 보지 않음
}

// [1220] 전략 게이트
let st: Strategy = PlayerState::strategy(player, rnd, game, game_vtable);   // 24B sret
if st.object_finish /*+0xf*/ != ObjectFinishStrategy::KillPriority /*0*/ {
    return false;
}

// [1224] 대상 오브젝트 엔티티 얻기 — objective_entity_id_for_main_objective(data, mo) 가 인라인됨(fight_model.rs:1178)
let moba = match game.game_mode() /*vtable+0x40*/ .as_moba() {   // GameMode tag==0 이면 Some
    Some(m) => m,
    None    => return true,      // MOBA 모드가 아니면 즉시 true
};
let live = if main_objective.tag == 0 { moba.jungle_runner.epic.live_list }    // [1181]
           else                       { moba.jungle_runner.serpen.live_list }; // [1183]
let id = match live.first().copied() { Some(id) => id, None => return true };  // len==0 → true
let objective: &Entity = match game.entity(id) /*vtable+0x1f0, [1225]*/ {
    Some(e) => e,
    None    => return true,
};

// [1229] 적팀 챔피언 순회 (컴파일러가 5칸 전부 언롤 — Option<&Entity> null 이면 스킵)
let et = 1 - player.info.team;               // 경계검사: et < 2 아니면 panic_bounds_check
let bb = &data.blackboard[et];               // Blackboard 744B
let champs = &data.cache.player_champion[et];// [Option<&Entity>; 5]

// [1230~1233] any 술어 (closure$1). 하나라도 true 면 전투 유지
return !champs.iter().flatten().any(|enemy| {
    // [1231]
    if !bb.is_recent_visible(game, game_vtable, player, enemy) { return false; }
    // [1232] is_ignored_well_enemy(version, player, enemy) 는 인라인됨(fight_model.rs:754)
    //        = (enemy.team == TeamType::Player(et)) && is_enemy_well_danger(version, player, enemy.x, enemy.y)
    if enemy.team.tag == 0 /*Player*/ && enemy.team.0 == et {
        if is_enemy_well_danger(version, player, enemy.x /*+0x660*/, enemy.y /*+0x668*/) { return false; }
    }
    // [1233]
    can_enemy_hit_objective(enemy, objective, 25000)
});
// 5칸을 다 돌아 아무도 술어를 만족 못 하면 [1235] true

// 정리 — true(전투 종료) 가 나오는 경로: ① GameMode≠Moba ② 해당 캠프 live_list 비어있음
//        ③ id 로 엔티티 조회 실패 ④ 적 챔피언 중 '최근 보이고 · 우물무시 대상 아니고 · 오브젝트를 때릴 수 있는' 자가 0명
//        false 가 나오는 경로: ⓐ 대상/페이즈 게이트 불통과 ⓑ object_finish≠KillPriority ⓒ 위 술어를 만족하는 적이 1명이라도 있음
